// Writes sgdb-key.js from a CLI arg or the OMNI_SGDB_KEY env var.
// Usage:
//   node scripts/set-key.js <key>
//   OMNI_SGDB_KEY=<key> npm run set-key          (macOS/Linux)
//   $env:OMNI_SGDB_KEY='<key>'; npm run set-key   (PowerShell)
const fs = require('fs');
const path = require('path');

const key = (process.argv[2] || process.env.OMNI_SGDB_KEY || '').trim();
if (!key) {
  console.error('No key provided. Pass it as an argument or set OMNI_SGDB_KEY.');
  process.exit(1);
}

const out = path.join(__dirname, '..', 'sgdb-key.js');
fs.writeFileSync(
  out,
  '// Generated by scripts/set-key.js — DO NOT COMMIT.\n' +
  'module.exports = { key: ' + JSON.stringify(key) + ' };\n'
);
console.log('Wrote', out);
